<template>
  <section class="role-section">
    <header><p class="eyebrow">Finance</p><h2>Payments and revenue</h2><p>A branch-level view of recorded transactions and recent activity.</p></header>
    <div class="metric-grid"><article v-for="metric in metrics" :key="metric.label" class="metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></div>
    <div class="panel-grid"><article class="panel"><h3>Revenue · last 7 days</h3><div class="bars"><div v-for="day in dailyTotals" :key="day.label"><span>{{ day.label }}</span><i><b :style="{ height: `${day.height}%` }" /></i><strong>{{ compactCurrency(day.total) }}</strong></div></div></article><article class="panel"><h3>Recent transactions</h3><div v-if="recentTransactions.length" class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-for="item in recentTransactions" :key="item.id"><td>{{ dateLabel(item) }}</td><td>{{ item.reference || item.id }}</td><td>{{ currency(item.amount) }}</td><td>{{ item.status || item.paymentStatus || 'Recorded' }}</td></tr></tbody></table></div><p v-else class="empty">No transactions to display.</p></article></div>
  </section>
</template>
<script setup>
import { computed } from 'vue'
const props = defineProps({ transactions: { type: Array, default: () => [] } })
const amount = item => Number(item.amount || item.total || 0)
const transactionDate = item => { const value = item.createdAt?.toDate?.() || item.createdAt || item.date || item.transactionDate; const date = new Date(value); return Number.isNaN(date.getTime()) ? null : date }
const localKey = date => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const todayKey = localKey(new Date())
const metrics = computed(() => { const today = props.transactions.filter(item => { const date = transactionDate(item); return date && localKey(date) === todayKey }); const month = props.transactions.filter(item => { const date = transactionDate(item); return date && date.getMonth() === new Date().getMonth() && date.getFullYear() === new Date().getFullYear() }); return [{ label: 'Today', value: currency(today.reduce((sum, item) => sum + amount(item), 0)), note: `${today.length} recorded transactions` }, { label: 'This month', value: currency(month.reduce((sum, item) => sum + amount(item), 0)), note: `${month.length} recorded transactions` }, { label: 'Transactions', value: props.transactions.length, note: 'Loaded for this branch' }] })
const dailyTotals = computed(() => { const now = new Date(); const days = Array.from({ length: 7 }, (_, index) => { const date = new Date(now); date.setDate(now.getDate() - (6 - index)); const key = localKey(date); const total = props.transactions.filter(item => { const value = transactionDate(item); return value && localKey(value) === key }).reduce((sum, item) => sum + amount(item), 0); return { label: date.toLocaleDateString(undefined, { weekday: 'short' }), total } }); const max = Math.max(1, ...days.map(day => day.total)); return days.map(day => ({ ...day, height: Math.max(day.total ? 8 : 0, Math.round(day.total / max * 100)) })) })
const recentTransactions = computed(() => [...props.transactions].sort((a, b) => (transactionDate(b)?.getTime() || 0) - (transactionDate(a)?.getTime() || 0)).slice(0, 8))
const currency = value => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP', maximumFractionDigits: 0 }).format(Number(value || 0))
const compactCurrency = value => value >= 1000 ? `₱${(value / 1000).toFixed(1)}k` : `₱${Math.round(value)}`
const dateLabel = item => transactionDate(item)?.toLocaleDateString() || '—'
</script>
<style scoped>
.role-section{display:grid;gap:1rem;color:#4a3324}.role-section header h2{margin:.25rem 0;font:600 1.65rem Georgia,serif;color:#402719}.role-section header p:last-child{margin:.3rem 0;color:#806b5a}.eyebrow{margin:0;color:#91643f;font-size:.68rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:.8rem}.metric,.panel{min-width:0;border:1px solid #ead8c2;border-radius:1rem;background:#fffdf9;padding:1rem;box-shadow:0 8px 24px #4b311e0a}.metric span,.metric small{display:block;color:#806b5a;font-size:.8rem}.metric strong{display:block;margin:.45rem 0;color:#4a2d1c;font-size:1.45rem;overflow-wrap:anywhere}.panel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:1rem}.panel h3{margin:0 0 .8rem;color:#4a2d1c;font-size:1rem}.bars{display:flex;align-items:stretch;justify-content:space-between;gap:.55rem;min-height:150px}.bars>div{display:grid;flex:1;grid-template-rows:auto 1fr auto;justify-items:center;gap:.4rem;color:#806b5a;font-size:.7rem}.bars i{display:flex;width:100%;height:100%;align-items:flex-end;overflow:hidden;border-radius:.5rem;background:#f2e8dc}.bars b{display:block;width:100%;border-radius:.5rem .5rem 0 0;background:#a97851}.bars strong{font-size:.68rem;color:#5a3b26}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:.82rem}th,td{padding:.65rem .5rem;border-bottom:1px solid #efe3d5;white-space:nowrap}th{color:#806b5a;font-size:.7rem;text-transform:uppercase;letter-spacing:.06em}.empty{color:#806b5a;font-size:.85rem}@media(max-width:600px){.role-section header h2{font-size:1.4rem}th,td{padding:.55rem .4rem;font-size:.75rem}}
</style>
